(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sy*0.025+t*0.4)*8+Math.cos(sx*0.02-t*0.15)*6;
  const w2y = Math.cos(sx*0.022-t*0.3)*8+Math.sin(sy*0.019+t*0.45)*6;
  const dx = sx+w2x, dy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 1.0],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.13, 1.6, 1.15],
    [200+Math.sin(t*0.25+6)*110, 220+Math.cos(t*0.45+3)*70, 0.075, 2.4, 0.95]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((dx-sX)**2+(dy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS += Math.sin(d*f*0.5-t*sp*0.3+3.0)*w*0.5;
  }
  const n=9, act=aS/n, inh=iS/n, cor=cS/n;
  const bg = (Math.sin(dx*0.04+dy*0.025+t*0.8)+Math.sin(dx*0.03-dy*0.04+t*1.1))/2
    +Math.sin((dx+dy)*0.12+t*2.5)*0.2+Math.sin((dx-dy)*0.1-t*2)*0.2;
  const bg2 = (Math.sin(dx*0.07-dy*0.05+t*1.3)+Math.cos(dx*0.05+dy*0.08-t*0.9))*0.15;
  const dist=Math.sqrt((dx-cx)**2+(dy-cy)**2), ang=Math.atan2(dy-cy,dx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2 = Math.sin(dist*0.08+ang*2-t*2.0)*Math.cos(dist*0.03-ang*5+t*1.8)*0.25;
  const moire = Math.sin(dist*0.15)*Math.sin(ang*6+t*0.5)*0.15;
  const reaction = Math.tanh((act-inh*0.65+cor*0.3+bg*0.3+spiral+spiral2+moire)*2.0);
  const cell = Math.tanh((Math.sin(dx*0.15)*Math.sin(dy*0.15)+Math.sin((dx+dy)*0.1+t)*0.5+Math.sin(dx*0.08-dy*0.06+t*0.7)*0.3)*1.5)*0.3;
  const micro = Math.sin(dx*0.3+t*3)*Math.sin(dy*0.3-t*2.5)*0.08;
  const blend = reaction*0.6+cell*0.25+micro, v = blend*0.5+0.5;
  const hueShift = Math.sin(t*0.15)*0.5+0.5;
  const pal1 = [[6,12,52],[12,45,88],[18,95,120],[30,160,150],[180,195,80],[210,155,60],[195,85,55],[140,35,55],[65,15,42],[6,12,52]];
  const pal2 = [[12,8,48],[40,20,80],[70,40,110],[110,80,140],[170,140,100],[200,170,70],[190,110,50],[150,50,60],[80,25,55],[12,8,48]];
  const pal = pal1.map((c,i) => c.map((ch,j) => ch+(pal2[i][j]-ch)*hueShift));
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edgeR = Math.abs(reaction)>0.75?1.2:Math.abs(reaction)>0.5?1.05:0.95;
  const glow = Math.max(0, 1-Math.abs(reaction)*1.5)*0.15;
  const sparkle = Math.sin(dx*0.5)*Math.sin(dy*0.5)*Math.sin(t*4)>0.92?0.3:0;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edgeR+glow*60+sparkle*80)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edgeR+glow*40+sparkle*90)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edgeR+glow*30+sparkle*100)|0)
  ];
}
